var e={id:`lukas-og-matteus`,episode:20,door:20,title:{nb:`Lukas og Matteus side om side`,en:`Luke and Matthew side by side`},reference:`Luk 1–2; Matt 1–2`,place:`cesarea`,prologue:[{image:`maps/cesarea-torg.webp`,text:{nb:`En kurer fra Antiokia kommer med fødselsfortellingen slik Matteus’ folk forteller den, fra Josefs side.`,en:`A courier from Antioch brings the birth story as Matthew’s people tell it, from Joseph’s side.`}},{image:`art/lukas.webp`,text:{nb:`Lukas legger de to fortellingene side om side, slik en dommer hører to vitner. Hva er de enige om, og hva gjør han der de er ulike?`,en:`Luke lays the two stories side by side, as a judge hears two witnesses. What do they agree on, and what does he do where they differ?`}}],intro:{nb:`Torget i Cæsarea, der kureren fra Antiokia nettopp har gått i land.`,en:`The square in Caesarea, where the courier from Antioch has just come ashore.`},outro:{nb:`Ulikt er ikke motsigelse. To fortellinger som ikke bygger på hverandre, er enige om kjernen; den er eldre enn begge. Der det kniper, sier vi fra.`,en:`Different is not contradictory. Two accounts that do not build on each other agree on the core, so it is older than both. Where it pinches, say so.`},map:[`################..##############`,`################..##############`,`##############....##############`,`#############.......############`,`############........############`,`#########......##.......########`,`##########.....###...###########`,`###########..........###########`,`###########.........############`,`######.#...###...##...##########`,`#####......###...##...##########`,`#####..#######...########.###..#`,`................................`,`..#.#..#.##..#....#..#..#..#.#..`,`########.##..#....#..#..########`,`#######..#############..########`,`#######..##############..#######`,`#######..##############..#######`,`#######..##############..#######`,`################################`,`################################`],background:`cesarea-torg.webp`,mood:`calm`,areas:[{id:`skrivestue`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######.....#########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`skrivestue.webp`,scale:1.8,ambience:`street`},{id:`dommerhus`,map:[`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`################################`,`######......########......######`,`######......########......######`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#####......................#####`,`#############......#############`,`#############......#############`,`#############......#############`,`################################`,`################################`,`################################`],background:`stue.webp`,scale:1.8,ambience:`hearth`}],start:{x:15,y:10},entities:[{id:`lukas`,kind:`person`,x:16,y:10,name:{nb:`Lukas`,en:`Luke`},look:`luke`,portrait:`lukas.webp`,interactions:[{not:[`oppdrag`],say:[{nb:`Snakk med kureren, grekeren, den gamle fra Jerusalem, pottemakeren og kona, og se på de to krukkene ved brønnen. Gå så inn i skrivestua og i dommerens hus.`,en:`Talk to the courier, the Greek, the old man from Jerusalem, the potter and his wife, and see the two jars by the well. Then the writing room and the judge.`}],set:[`oppdrag`]},{has:[`felles-lost`,`ulikt-lost`,`to-tavler-lost`,`uavhengig-lost`,`egypt-lost`,`metoden-lost`],not:[`avsluttet`],say:[{nb:`Godt arbeid. Teofilos skal få se det samme som jeg, også der det kniper.`,en:`Good work. Theophilus will see what I see, awkward parts included.`},{nb:`I morgen: hva som skjer med det jeg skriver når det kopieres, avskrift etter avskrift.`,en:`Tomorrow: what happens to what I write when it is copied, copy after copy.`}],set:[`avsluttet`]},{has:[`spor:antiokia-ark`],not:[`felles-lost`],say:[{nb:`Sakene venter i vitneboka.`,en:`The cases are waiting in the notebook.`}]},{say:[{nb:`Kureren, grekeren, den gamle, pottemakeren, kona og krukkene ved brønnen. Skrivestua og dommerens hus.`,en:`The courier, the Greek, the old man, the potter, his wife and the jars by the well. The writing room and the judge’s house.`}]}]},{id:`dor-skrivestue`,kind:`place`,x:14,y:2,name:{nb:`Skrivestua`,en:`The writing room`},look:`hotspot`,door:{area:`skrivestue`,x:15,y:14}},{id:`dor-dommerhus`,kind:`place`,x:25,y:11,name:{nb:`Dommerens hus`,en:`The judge’s house`},look:`hotspot`,door:{area:`dommerhus`,x:15,y:14}},{id:`kurer`,kind:`person`,x:12,y:8,name:{nb:`Kureren fra Antiokia`,en:`The courier from Antioch`},look:`courier`,portrait:`courier.webp`,interactions:[{has:[`oppdrag`],not:[`spor:kurer`],say:[{nb:`Jeg kom med skipet i natt. Rullen er fra menigheten i Antiokia, der de som fulgte Matteus, holder til.`,en:`I came on the ship last night. The scroll is from the church in Antioch, where those who followed Matthew gather.`},{nb:`De forteller fødselen fra Josefs side: drømmene hans, de lærde mennene fra Østen, Herodes, flukten til Egypt.`,en:`They tell the birth from Joseph’s side: his dreams, the learned men from the East, Herod, the flight to Egypt.`},{nb:`Hyrder, krybbe, folketelling? Ikke et ord. De sa: vi forteller det vi fikk.`,en:`Shepherds, a manger, a census? Not a word. They said: we tell what we were given.`}],set:[`spor:kurer`,`fakta:matteus`]},{has:[`bit:1`,`bit:2`,`bit:3`,`bit:4`],not:[`rull-helet`],say:[{nb:`Alle fire! Drømmen, de lærde mennene, Egypt. Nå kan Lukas lese det hele.`,en:`All four! The dream, the learned men, Egypt. Now Luke can read the whole of it.`}],set:[`rull-helet`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{has:[`spor:kurer`],not:[],say:[{nb:`Brevet som fulgte rullen, er skrevet med forskjøvne bokstaver, slik Cæsar gjorde når veien var usikker. Snu hjulet til ordene kan leses, så vet vi hva brevet sier om rullen.`,en:`The letter with the scroll is in shifted letters, as Caesar wrote when the roads were unsafe. Turn the wheel until the words make sense, and we will know what it says.`}],play:{game:`cipher`,title:{nb:`Tyd brevet`,en:`Decode the letter`},win:`brevet-tydet`,data:{words:[{nb:`VITNE`,en:`WITNESS`},{nb:`ANTIOKIA`,en:`ANTIOCH`},{nb:`RULLEN`,en:`SCROLL`},{nb:`BETLEHEM`,en:`BETHLEHEM`},{nb:`EGYPT`,en:`EGYPT`}]},key:!0}}]},{id:`greker`,kind:`person`,x:18,y:8,name:{nb:`Grekeren som ikke tror`,en:`The Greek who does not believe`},look:`trader`,portrait:`trader.webp`,interactions:[{has:[`oppdrag`],not:[`spor:greker`],say:[{nb:`To fortellinger om samme fødsel, og så ulike? Da lyver minst én. Lærde menn mot gjetere, Egypt mot Nasaret. Velg.`,en:`Two stories of the same birth, and so different? Then at least one is lying. Learned men against shepherds, Egypt against Nazareth. Choose.`},{nb:`Og Betlehem har dere begge fra profeten Mika. Han sa at en hersker skulle komme derfra, så dere la fødselen dit.`,en:`And you both have Bethlehem from the prophet Micah. He said a ruler would come from there, so you put the birth there.`},{nb:`Og slektstavlene! Jeg har sett begge. Josefs far heter Jakob hos den ene og Eli hos den andre. Be Lukas forklare det.`,en:`And the genealogies! I have seen both. Joseph’s father is Jacob in one and Heli in the other. Let Luke explain that.`}],set:[`spor:greker`,`spor:innvending`]},{say:[{nb:`Velg én. Begge kan ikke være sanne. Eller?`,en:`Choose one. They cannot both be true. Or can they?`}]}]},{id:`gammel`,kind:`person`,x:23,y:13,name:{nb:`Den gamle fra Jerusalem`,en:`The old man from Jerusalem`},look:`beggar`,portrait:`beggar.webp`,interactions:[{has:[`oppdrag`],not:[`spor:gammel`],say:[{nb:`Slektstavler? Dem tar vi alvorlig. Prestenes ligger i templets arkiv, og Davids ætt har også sine.`,en:`Genealogies? We take those seriously. The priests’ are kept in the temple archive, and David’s line keeps its own.`},{nb:`Loven om svogerekteskap kan gi samme mann to tavler: dør en mann barnløs, gifter broren seg med enka, og sønnen regnes som den dødes.`,en:`Levirate marriage can give one man two family trees: if a man dies childless, his brother marries the widow, and the son counts as the dead man’s.`},{nb:`Én far for loven, én for blodet. Men om det er slik her, vet jeg ikke.`,en:`One father by law, one by blood. Whether that is so here, I do not know.`}],set:[`spor:gammel`,`fakta:slektstavler`]},{say:[{nb:`Én far for loven, én for blodet. Kanskje. Jeg vet ikke.`,en:`One father for the law, one for the blood. Perhaps. I do not know.`}]}]},{id:`pottemaker`,kind:`person`,x:19,y:7,name:{nb:`Pottemakeren`,en:`The potter`},look:`potter`,portrait:`potter.webp`,interactions:[{has:[`oppdrag`],not:[`spor:pottemaker`],say:[{nb:`Kona og jeg så kjerra som veltet her på torget. Da vi vitnet, sa vi ulikt om det små: jeg så eselet, hun så krukkene.`,en:`My wife and I saw the cart tip over here in the square. When we testified, we differed on small things: I saw the donkey, she saw the jars.`},{nb:`Men om det store sa vi det samme. Slik blir det når to har sett det samme uten å snakke sammen først.`,en:`But on the big things we agreed. That is how it is when two people see the same thing and do not talk it over first.`}],set:[`spor:pottemaker`]},{has:[`spor:pottemaker`],not:[`krukkene-truffet`],say:[{nb:`Krukkene som sprakk i ovnen, står bak boden. De skal knuses uansett. Treff fire av dem!`,en:`The jars that cracked in the kiln stand behind the stall. They are to be smashed anyway. Hit four of them!`}],play:{game:`toss`,title:{nb:`Kast på krukkene`,en:`Throw at the jars`},win:`krukkene-truffet`}},{has:[`spor:dommer`],not:[`tavle-hans`],say:[{nb:`Mitt vitnemål, på tavle: eselet, hjulet. Ta det til dommeren.`,en:`My statement, on a tablet: the donkey, the wheel. Take it to the judge.`}],set:[`tavle-hans`]},{say:[{nb:`Likt om det store, ulikt om det små. Da har de sett det.`,en:`Alike on the big, different on the small. Then they have seen it.`}]}]},{id:`kone`,kind:`person`,x:12,y:4,name:{nb:`Pottemakerens kone`,en:`The potter’s wife`},look:`bakerwife`,portrait:`bakerwife.webp`,interactions:[{has:[`oppdrag`],not:[`spor:kone`],say:[{nb:`Fra bakeriet så jeg bare krukkene som falt. Mannen min så eselet. Samme kjerre.`,en:`From the bakery I saw only the jars that fell. My husband saw the donkey. Same cart.`},{nb:`Maria og Josef, tenker jeg. Hun husket engelen som kom til henne, gjeterne, det hun gjemte i hjertet. Han husket drømmene sine. Hvem skulle ellers vite om Josefs drømmer enn Josef?`,en:`Mary and Joseph, I think. She remembered the angel who came to her, the shepherds, what she kept in her heart. He remembered his dreams. Who but Joseph would know his dreams?`}],set:[`spor:kone`]},{has:[`spor:dommer`],not:[`tavle-hennes`],say:[{nb:`Mitt: krukkene som falt. Ta det med.`,en:`Mine: the jars that fell. Take it along.`}],set:[`tavle-hennes`]},{say:[{nb:`Hennes side og hans side. Samme barn.`,en:`Her side and his side. Same child.`}]}]},{id:`jente`,kind:`person`,x:14,y:6,name:{nb:`Jenta`,en:`The girl`},look:`girl`,portrait:`girl.webp`,interactions:[{say:[{nb:`To ruller om det samme barnet? Mor sier at to vitner er bedre enn ett, så lenge de ikke har øvd sammen.`,en:`Two scrolls about the same child? Mother says two witnesses are better than one, as long as they have not rehearsed together.`}]}]},{id:`soldat`,kind:`person`,x:26,y:13,name:{nb:`Soldaten`,en:`The soldier`},look:`soldier`,portrait:`soldier.webp`,interactions:[{say:[{nb:`Herodes den store? Bestefar tjente under ham. Han drepte tre av sønnene sine og kona si.`,en:`Herod the Great? My grandfather served under him. He killed three of his sons and his wife.`},{nb:`Keiseren skal ha sagt at det var tryggere å være Herodes’ gris enn hans sønn. At han kunne drepe barn i en landsby? Spør bestefar.`,en:`The emperor is said to have remarked it was safer to be Herod’s pig than his son. Would he kill children in a village? Ask my grandfather.`}],set:[`spor:soldat`,`fakta:herodes`],has:[],not:[`spor:soldat`]},{say:[{nb:`Tryggere å være Herodes’ gris enn hans sønn.`,en:`Safer to be Herod’s pig than his son.`}],has:[],not:[],set:[]}]},{id:`to-krukker`,kind:`thing`,x:16,y:7,name:{nb:`To krukker ved brønnen`,en:`Two jars by the well`},look:`hotspot`,interactions:[{say:[{nb:`To krukker fra samme leire, dreid av to hender. Ikke like. Samme leire.`,en:`Two jars from the same clay, turned by two hands. Not alike. Same clay.`}],set:[`spor:krukker`]}]},{id:`vei-jerusalem`,kind:`place`,x:31,y:12,name:{nb:`Veien til Jerusalem`,en:`The road to Jerusalem`},look:`hotspot`,travelTo:`jerusalem`},{id:`vei-havna`,kind:`place`,x:0,y:12,name:{nb:`Til dagen ved tollboden`,en:`To the day at the customs house`},look:`hotspot`,travel:`keiserens-befaling`},{id:`dor-ut-skrivestue`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:15,y:2},area:`skrivestue`},{id:`lukas-ark`,kind:`thing`,x:8,y:7,name:{nb:`Lukas’ ark`,en:`Luke’s sheet`},look:`hotspot`,interactions:[{say:[{nb:`Det jeg har: engelen til Sakarja og til Maria i Nasaret; Maria hos Elisabet; Johannes fødes; keiserens befaling; Betlehem, krybben, gjeterne;`,en:`What I have: the angel to Zechariah and to Mary in Nazareth; Mary with Elizabeth; John is born; the emperor’s decree; Bethlehem, the manger, the shepherds;`},{nb:`omskjæringen og navnet; templet, Simeon og Anna; hjem til Nasaret. Maria forlovet med Josef av Davids ætt. Barnet ved Den hellige ånd. Under Herodes.`,en:`the circumcision and the name; the temple, Simeon and Anna; home to Nazareth. Mary betrothed to Joseph of David’s line. The child by the Holy Spirit. Under Herod.`}],set:[`spor:lukas-ark`]}],area:`skrivestue`},{id:`antiokia-ark`,kind:`thing`,x:22,y:7,name:{nb:`Rullen fra Antiokia`,en:`The scroll from Antioch`},look:`hotspot`,interactions:[{say:[{nb:`Det de har: Josef oppdager at Maria venter barn og vil skille seg stille. En engel i drømme sier at barnet er av Den hellige ånd og skal hete Jesus.`,en:`What they have: Joseph finds Mary is expecting and means to break it off quietly. In a dream an angel says the child is from the Holy Spirit, and to name him Jesus.`},{nb:`Født i Betlehem i Herodes’ dager; lærde menn fra Østen følger en stjerne. Herodes dreper guttebarna under to år i Betlehem; flukt til Egypt, og etter Herodes’ død til Nasaret. Josef av Davids ætt.`,en:`Born in Bethlehem under Herod; learned men from the East follow a star. Herod kills Bethlehem’s boys under two; flight to Egypt, and after Herod dies, to Nazareth. Joseph of David’s line.`}],set:[`spor:antiokia-ark`]}],area:`skrivestue`},{id:`slektstavlene`,kind:`thing`,x:15,y:9,name:{nb:`De to slektstavlene`,en:`The two genealogies`},look:`hotspot`,interactions:[{say:[{nb:`To ark ved siden av hverandre. Begge går fra David til Josef.`,en:`Two sheets side by side. Both go from David to Joseph.`},{nb:`Antiokia-rullen går gjennom Salomo og kongene, tre ganger fjorten ledd, og Josefs far heter Jakob.`,en:`The Antioch scroll goes through Solomon and the kings, three times fourteen generations, and Joseph’s father is called Jacob.`},{nb:`Min går gjennom Natan, en annen sønn av David, og helt tilbake til Adam, og Josefs far heter Eli. Fra David og ned er nesten alle navnene ulike.`,en:`Mine goes through Nathan, another son of David, all the way back to Adam, and Joseph’s father is Heli. From David down, nearly all the names differ.`}],set:[`spor:slektstavlene`]}],area:`skrivestue`},{id:`notat`,kind:`thing`,x:18,y:9,name:{nb:`Lukas’ notat`,en:`Luke’s note`},look:`hotspot`,interactions:[{say:[{nb:`Et ark: «Jeg har ikke hatt rullen fra Antiokia før nå, og de har ikke hatt min.»`,en:`A sheet: “I have not had the scroll from Antioch until now, and they have not had mine.”`},{nb:`«Likevel: samme foreldre, samme by, samme konge, samme navn gitt av en engel, samme ætt, samme ord om Ånden. Det kan ingen av oss ha fått fra den andre. Det er eldre enn oss begge.»`,en:`“Yet: same parents, same town, same king, same name given by an angel, same line, same word about the Spirit. Neither of us got that from the other. It is older than both of us.”`}],set:[`spor:notat`]}],area:`skrivestue`},{id:`mika`,kind:`thing`,x:26,y:9,name:{nb:`Rullen med Mika`,en:`The scroll of Micah`},look:`hotspot`,interactions:[{say:[{nb:`Mika om Betlehem: fra deg, minste blant Judas byer, skal det komme en hersker over Israel, med opphav fra gammel tid. Antiokia-rullen siterer dette; jeg siterer det ikke, men begge har Betlehem.`,en:`Micah on Bethlehem: small among Judah’s towns, yet a ruler over Israel will come from it, one whose roots are ancient. The Antioch scroll quotes this; I do not, but both have Bethlehem.`}],set:[`spor:mika`]}],area:`skrivestue`},{id:`dor-ut-dommerhus`,kind:`place`,x:15,y:17,name:{nb:`Ut på torget`,en:`Out to the square`},look:`hotspot`,door:{area:`main`,x:25,y:12},area:`dommerhus`},{id:`dommer`,kind:`person`,x:20,y:9,name:{nb:`Dommeren`,en:`The judge`},look:`scribe`,portrait:`scribe.webp`,interactions:[{has:[`oppdrag`],not:[`spor:dommer`],say:[{nb:`Loven sier at en sak skal stå på to eller tre vitner, og jeg hører dem hver for seg.`,en:`The law says a case is to stand on two or three witnesses, and I hear them separately.`},{nb:`Sier de det samme ord for ord, har noen øvd dem. Sier de ulikt om alt, tror jeg ingen av dem. Sier de likt om saken og ulikt om småtingene, har jeg to vitner.`,en:`If they say the same word for word, someone has coached them. If they differ on everything, I believe neither. If they agree on the main thing and differ on small things, I have two witnesses.`},{nb:`Pottemakeren nevner eselet, kona hans ikke. Det er ikke motsigelse. Det er motsigelse når begge ikke kan være sanne samtidig. Da må jeg velge, eller si at jeg ikke vet.`,en:`The potter mentions the donkey, his wife does not. That is not a contradiction. A contradiction is when both cannot be true at once. Then I must choose, or say I do not know.`}],set:[`spor:dommer`,`spor:motsigelse`,`fakta:to-vitner`]},{has:[`tavle-hans`,`tavle-hennes`],not:[`to-vitner-hort`],say:[{nb:`Likt om saken, ulikt om småting. To vitner. Slik leser jeg også de to rullene.`,en:`Alike on the matter, different on the details. Two witnesses. That is how I read the two scrolls, too.`}],set:[`to-vitner-hort`]},{not:[`oppdrag`],say:[{nb:`Snakk med Lukas først.`,en:`Speak with Luke first.`}]},{has:[`to-vitner-hort`],not:[],say:[{nb:`Likt om saken, ulikt om småtingene. Da har jeg to vitner.`,en:`Alike on the matter, different on the small things. Then I have two witnesses.`}],set:[]},{say:[{nb:`Hent vitnemålene til pottemakeren og kona, så skal du se hvordan jeg leser dem.`,en:`Fetch the testimonies of the potter and his wife, and you will see how I read them.`}]}],area:`dommerhus`},{id:`lovrull`,kind:`thing`,x:15,y:9,name:{nb:`Rullen med loven om vitner`,en:`The scroll with the law on witnesses`},look:`hotspot`,interactions:[{say:[{nb:`Moseloven: ett vitne er ikke nok mot noen; på to eller tre vitners ord skal en sak stå.`,en:`The law of Moses: one witness is not enough to convict anyone; a case needs two or three witnesses.`}],set:[`spor:lovrull`]}],area:`dommerhus`},{id:`tavle`,kind:`thing`,x:23,y:7,name:{nb:`Dommerens tavle`,en:`The judge’s tablet`},look:`hotspot`,interactions:[{say:[{nb:`En vokstavle med to spalter: «Vitne 1» og «Vitne 2», og en strek under hvert punkt de er enige om. Det er slik han sammenligner.`,en:`A wax tablet with two columns: “Witness 1” and “Witness 2”, and a line under every point where they agree. That is how he compares.`}],set:[`spor:tavle`]}],area:`dommerhus`},{id:`rullbit-1`,kind:`thing`,x:3,y:13,name:{nb:`En rullbit`,en:`A piece of scroll`},look:`scrap`,hiddenWhen:`bit:1`,interactions:[{say:[{nb:`En bit av rullen fra Antiokia, blåst bort fra kaia.`,en:`A piece of the scroll from Antioch, blown away from the quay.`}],set:[`bit:1`]}]},{id:`rullbit-2`,kind:`thing`,x:7,y:17,name:{nb:`En rullbit`,en:`A piece of scroll`},look:`scrap`,hiddenWhen:`bit:2`,interactions:[{say:[{nb:`En bit av rullen fra Antiokia, blåst bort fra kaia.`,en:`A piece of the scroll from Antioch, blown away from the quay.`}],set:[`bit:2`]}]},{id:`rullbit-3`,kind:`thing`,x:22,y:5,name:{nb:`En rullbit`,en:`A piece of scroll`},look:`scrap`,hiddenWhen:`bit:3`,interactions:[{say:[{nb:`En bit av rullen fra Antiokia, blåst bort fra kaia.`,en:`A piece of the scroll from Antioch, blown away from the quay.`}],set:[`bit:3`]}]},{id:`rullbit-4`,kind:`thing`,x:16,y:14,name:{nb:`En rullbit`,en:`A piece of scroll`},look:`scrap`,hiddenWhen:`bit:4`,interactions:[{say:[{nb:`En bit av rullen fra Antiokia, blåst bort fra kaia.`,en:`A piece of the scroll from Antioch, blown away from the quay.`}],set:[`bit:4`]}]},{id:`leke-baat`,kind:`thing`,x:24,y:16,name:{nb:`Båten ved brygga`,en:`The boat by the jetty`},look:`hotspot`,interactions:[{say:[{nb:`Du ror et lite stykke ut og tilbake. Kureren fra Antiokia ser bort. Han har fått nok av båter for en stund.`,en:`You row a little way out and back. The courier from Antioch looks away. He has had enough of boats for a while.`}],fx:`rock`}]},{id:`leke-frukt`,kind:`thing`,x:13,y:3,name:{nb:`Fruktboden`,en:`The fruit stall`},look:`hotspot`,interactions:[{say:[{nb:`Eplene triller i to retninger.`,en:`The apples roll off in two directions.`},{nb:`Selgeren peker på deg: «To vitner så det, og begge sier det var deg!»`,en:`The seller points at you: “Two witnesses saw it, and both say it was you!”`}],fx:`tip`}]},{id:`leke-skaal`,kind:`thing`,x:14,y:13,name:{nb:`Bronseskåla`,en:`The bronze bowl`},look:`hotspot`,interactions:[{say:[{nb:`Skåla klinger lenge. Grekeren som ikke tror, nikker: «Pent. Men det beviser ingenting.»`,en:`The bowl rings a long time. The Greek who does not believe nods: “Pretty. But it proves nothing.”`}],fx:`ring`}]},{id:`leke-palme`,kind:`thing`,x:17,y:2,name:{nb:`Palmen`,en:`The palm tree`},look:`hotspot`,interactions:[{say:[{nb:`En daddel faller, og så en til. To dadler fra samme tre, men ikke helt like.`,en:`One date falls, and then another. Two dates from the same tree, but not quite alike.`}],fx:`shake`}]},{id:`leke-vinde`,kind:`thing`,x:17,y:5,name:{nb:`Brønnvinda`,en:`The well windlass`},look:`hotspot`,interactions:[{say:[{nb:`Vinda knirker rundt, og bøtta kommer opp full av kaldt vann.`,en:`The windlass creaks round, and the bucket comes up full of cold water.`}],fx:`spin`}]}],facts:[{id:`to-vitner`,title:{nb:`To uavhengige fortellinger`,en:`Two independent stories`},body:{nb:`Kort sagt: Matteus og Lukas forteller ulikt, men er enige om kjernen, og det er den som er eldst. Matteus 1–2 og Lukas 1–2 er så ulike at de fleste forskere regner dem som uavhengige av hverandre. Likevel er de enige om en kjerne: Maria og Josef forlovet; Josef av Davids ætt; barnet unnfanget ved Den hellige ånd uten en mann; navnet Jesus gitt av en engel før fødselen; født i Betlehem i Herodes den stores dager; oppvokst i Nasaret. Raymond Brown lister elleve slike punkter. Kriteriet heter «flerfoldig uavhengig bevitnelse»: det to kilder har uten å ha lest hverandre, er eldre enn begge. Merk hva det viser: at kjernen er eldre enn begge bøkene, ikke i seg selv at den går helt tilbake til Maria og Josef. At Lukas bygger på Marias side og Matteus på Josefs, er en gammel og rimelig gjetning, ikke noe evangeliene sier. Brown selv, som satte opp lista, var forsiktig med hvor mye av fortellingene han regnet som historie. En annen innvending: begge kan ha lagt fødselen til Betlehem fordi Mika hadde sagt det. Mot det taler at Lukas ikke siterer Mika og gir en helt annen grunn (folketellingen); Betlehem lå altså i tradisjonen før noen brukte profetien på den. William Lane Craig bruker det om jomfrufødselen: den står i to uavhengige kilder.`,en:`In short, Matthew and Luke tell it differently but agree on the core, and the core is the oldest part. Matthew 1–2 and Luke 1–2 are so different that most scholars count them as independent of each other. Yet they agree on a core: Mary and Joseph betrothed; Joseph of David’s line; the child conceived by the Holy Spirit without a man; the name Jesus given by an angel before the birth; born in Bethlehem in the days of Herod the Great; raised in Nazareth. Raymond Brown lists eleven such points. The criterion is called “multiple independent attestation”: what two sources have without having read each other is older than both. Note what that shows: that the core is older than both books, not by itself that it goes all the way back to Mary and Joseph. That Luke builds on Mary’s side and Matthew on Joseph’s is an old and reasonable guess, not something the Gospels say. Brown himself, who drew up the list, was cautious about how much of the stories he counted as history. Another objection: both may have placed the birth in Bethlehem because Micah had said so. Against that: Luke does not quote Micah and gives a quite different reason (the census); Bethlehem was in the tradition before anyone applied the prophecy to it. William Lane Craig applies it to the virgin birth: it stands in two independent sources.`},unlockedBy:`fakta:to-vitner`,link:`https://bibleproject.com/videos/matthew-1-13/`},{id:`matteus`,title:{nb:`Matteusevangeliet`,en:`The Gospel of Matthew`},body:{nb:`Kort sagt: Matteus’ bok er trolig yngre enn Lukas’, men fortellingene hans kan ha gått i menighetene lenge før. Det første evangeliet i Det nye testamente ble tidlig knyttet til tolleren Matteus (Papias, ca. 110). Det er skrevet for jødekristne lesere, siterer Skriftene ofte («for at det skulle oppfylles»), og forteller fødselen fra Josefs side: drømmene, de lærde mennene, Egypt. De fleste forskere daterer det til 80–90, noen tidligere. Antiokia i Syria er det stedet flest gjetter på. Kureren og rullen i dette kapitlet er spillets grep: ingen kilde sier at Lukas så Matteus’ fortelling skrevet ned, og Matteusevangeliet slik vi har det, er trolig yngre enn Lukas’ tid omkring år 60. Men stoffet kan ha gått i menighetene lenge før det ble bok; det er det kureren bærer. De fleste forskere mener Lukas ikke kjente Matteus’ bok. Et mindretall (Farrer, Goodacre) mener han gjorde det, og at han bevisst fortalte fødselen annerledes. Har de rett, er de to fødselsfortellingene ikke to uavhengige vitner, og argumentet i dette kapitlet må bygges annerledes. Spillet følger flertallet, og sier fra om at det er et valg.`,en:`In short, Matthew’s book is probably later than Luke’s, but his stories may have circulated in the churches long before it was written down. The first Gospel in the New Testament was linked early on to the tax collector Matthew (Papias, c. 110). It is written for Jewish-Christian readers, quotes the Scriptures often (“that it might be fulfilled”), and tells the birth from Joseph’s side: the dreams, the learned men, Egypt. Most scholars date it to 80–90; some earlier. Antioch in Syria is the most common guess. The courier and the scroll in this chapter are the game’s device: no source says Luke saw Matthew’s story in writing, and Matthew’s Gospel as we have it is probably later than Luke’s time around AD 60. But the material may have circulated in the churches long before it became a book; that is what the courier carries. Most scholars think Luke did not know Matthew’s book. A minority (Farrer, Goodacre) think he did, and that he deliberately told the birth differently. If they are right, the two birth stories are not two independent witnesses, and the argument of this chapter has to be built another way. The game follows the majority, and says that this is a choice.`},unlockedBy:`fakta:matteus`,film:`https://vimeo.com/146909450`},{id:`slektstavler`,title:{nb:`De to slektstavlene`,en:`The two genealogies`},body:{nb:`Kort sagt: De to slektstavlene stemmer ikke med hverandre, og ingen forklaring kan bevises. Matt 1,1–17 går fra Abraham til Josef gjennom Salomo og kongene, i 3 × 14 ledd; Luk 3,23–38 går fra Josef tilbake til Adam gjennom Natan, en annen av Davids sønner. Fra David til Josef har de nesten ingen felles navn, og Josefs far heter Jakob hos Matteus og Eli hos Lukas. Forslagene er gamle: Julius Africanus (ca. 220) forklarte det med svogerekteskap (5 Mos 25,5–6), slik at Josef hadde én juridisk og én biologisk far; fra omkring 1500 (Annius fra Viterbo) har mange ment at Lukas følger Marias slekt; andre at Matteus gir tronfølgen og Lukas blodslinjen. Ingen av forslagene kan bevises. Begge tavlene går gjennom Josef, enda begge evangelier sier at Josef ikke var far til barnet. I jødisk rett gjaldt den som tok barnet som sitt, som far; det er samme tanke som i svogerekteskapet. Josefus (Vita 1) viser at slektstavler ble ført i offentlige arkiver, og Hegesippus forteller at Jesu slektninger ble forhørt av Domitian som Davids ætt (Eusebius, Kirkehistorien 3,20). At prester måtte kunne vise ætten sin, ser vi i Esra 2,62, og Josefus forteller at prestenes slektslister ble ført nøye (Mot Apion 1,30–36). Julius Africanus forteller at Jesu slektninger fra landsbyene Nasaret og Kokaba holdt rede på slekta si (Eusebius, Kirkehistorien 1,7).`,en:`In short, the two genealogies do not match, and no explanation can be proved. Matt 1:1–17 goes from Abraham to Joseph through Solomon and the kings, in 3 × 14 generations; Luke 3:23–38 goes from Joseph back to Adam through Nathan, another of David’s sons. From David to Joseph they have almost no names in common, and Joseph’s father is Jacob in Matthew and Heli in Luke. The proposals are old: Julius Africanus (c. 220) explained it by levirate marriage (Deut 25:5–6), so that Joseph had one legal and one biological father; since around 1500 (Annius of Viterbo) many have held that Luke follows Mary’s family; others that Matthew gives the royal succession and Luke the bloodline. None of the proposals can be proved. Both tables run through Joseph, though both Gospels say Joseph was not the child’s father. In Jewish law the man who took the child as his own counted as father; it is the same idea as in levirate marriage. Josephus (Life 1) shows that genealogies were kept in public archives, and Hegesippus reports that Jesus’ relatives were questioned by Domitian as David’s line (Eusebius, Church History 3.20). That priests had to be able to show their descent can be seen in Ezra 2:62, and Josephus says priestly family records were kept carefully (Against Apion 1.30–36). Julius Africanus reports that Jesus’ relatives from the villages of Nazareth and Kochaba kept track of their family line (Eusebius, Church History 1.7).`},unlockedBy:`fakta:slektstavler`},{id:`egypt`,title:{nb:`Egypt og Nasaret`,en:`Egypt and Nazareth`},body:{nb:`Kort sagt: Egypt-reisen og tempelbesøket kan gå opp, men det er trangt. Matteus forteller om de lærde mennene, flukten til Egypt og hjemkomsten til Nasaret etter Herodes’ død (Matt 2); Lukas om templet etter førti dager og hjemreisen til Nasaret (Luk 2,39), uten Egypt. Lukas sier ikke at de dro straks, og Matteus lar de lærde mennene komme til et «hus» og Herodes drepe gutter «under to år», som gir rom for tid. En rekkefølge der templet kommer først, så de lærde mennene og Egypt, er mulig, men begge evangelistene forteller som om deres vei var den eneste. Det er også en annen knute: Matteus forteller som om Josef først ville slå seg ned i Judea og valgte Galilea fordi Arkelaos hersket der (Matt 2,22–23), mens hos Lukas er Nasaret hjemmet deres fra før (Luk 1,26; 2,4). Ærlig sagt: Det går opp, men det er trangt, og det er et av stedene kritikere peker på.`,en:`In short, the Egypt journey and the temple visit can fit together, but it is tight. Matthew tells of the learned men, the flight to Egypt and the return to Nazareth after Herod’s death (Matt 2); Luke of the temple after forty days and the journey home to Nazareth (Luke 2:39), without Egypt. Luke does not say they went at once, and Matthew has the learned men come to a “house” and Herod kill boys “under two”, which leaves room for time. An order where the temple comes first, then the learned men and Egypt, is possible, but both evangelists tell it as if their route were the only one. There is another knot too: Matthew tells it as if Joseph first meant to settle in Judea and chose Galilee because Archelaus ruled in Judea (Matt 2:22–23), while in Luke Nazareth is their home from the start (Luke 1:26; 2:4). To be honest: it adds up, but it is tight, and it is one of the places critics point to.`},unlockedBy:`egypt-lost`},{id:`vitneloven`,title:{nb:`Loven om to vitner`,en:`The law of two witnesses`},body:{nb:`Loven sier at en sak skal stå på to eller tre vitners ord (5 Mos 19,15; jf. 17,6). Jesus og Paulus viser til regelen (Matt 18,16; 2 Kor 13,1). J. Warner Wallace, som etterforsket uoppklarte drapssaker og var ateist da han begynte å lese evangeliene, peker på at ekte vitner nesten alltid avviker i detaljer og synsvinkel, og at helt like forklaringer er tegn på samordning. Han bruker det om evangeliene der de forteller uavhengig av hverandre, som i fødselsfortellingene: ulike i det små, enige om det store. (Der Matteus og Lukas er ordrett like, er det fordi begge har brukt Markus som kilde; det er en annen sak.)`,en:`The law says that a case shall stand on the word of two or three witnesses (Deut 19:15; cf. 17:6). Jesus and Paul refer to the rule (Matt 18:16; 2 Cor 13:1). J. Warner Wallace, who investigated cold-case murders and was an atheist when he began reading the Gospels, points out that genuine witnesses nearly always differ in details and point of view, and that identical statements are a sign of collusion. He applies it to the Gospels where they tell independently of each other, as in the birth stories: different in small things, agreed on the big ones. (Where Matthew and Luke are alike word for word, it is because both used Mark as a source; that is another matter.)`},unlockedBy:`fakta:to-vitner`},{id:`herodes`,title:{nb:`Herodes den store`,en:`Herod the Great`},body:{nb:`Herodes (konge 37–4 f.Kr.) bygde ut templet, Cæsarea og Masada, og drepte kona Mariamne, tre sønner og mange andre han fryktet. Josefus forteller at han på dødsleiet ville la fremstående jøder henrette for at folk skulle sørge når han døde (Ant. 17,174–181). Keiser Augustus skal ha sagt at han heller ville være Herodes’ gris enn hans sønn (Makrobius, Saturnalia 2,4,11). Makrobius skrev rundt år 400, og formen han gir utsagnet, kan være farget av Matteus’ fortelling; det er et vitne om Herodes’ rykte, ikke om Betlehem. Drapet på guttebarna i Betlehem (Matt 2,16) er ikke nevnt hos Josefus, men passer mannen; en landsby på noen hundre mennesker hadde kanskje et dusin gutter under to år.`,en:`Herod (king 37–4 BC) built up the temple, Caesarea and Masada, and killed his wife Mariamne, three sons and many others he feared. Josephus says that on his deathbed he wanted leading Jews executed so that people would mourn when he died (Ant. 17.174–181). Emperor Augustus is said to have remarked that he would rather be Herod’s pig than his son (Macrobius, Saturnalia 2.4.11). Macrobius wrote around AD 400, and the form he gives the saying may be coloured by Matthew’s story; it is a witness to Herod’s reputation, not to Bethlehem. The killing of the boys in Bethlehem (Matt 2:16) is not mentioned by Josephus, but fits the man; a village of a few hundred people had perhaps a dozen boys under two.`},unlockedBy:`fakta:herodes`},{id:`diktet`,title:{nb:`Hva er funnet på i denne episoden?`,en:`What is made up in this episode?`},unlockedBy:`metoden-lost`,body:{nb:`Kureren, grekeren, den gamle fra Jerusalem, pottemakeren og kona hans, dommeren, soldaten og jenta er funnet på, og det samme er det de sier. Brevet med forskjøvne bokstaver, dommerens hus og tavla hans er laget for spillet. Vi vet ikke om Lukas noen gang så Matteus’ fortelling; de fleste forskere mener at han ikke gjorde det. De to fortellingene står i Matt 1–2 og Luk 1–2.`,en:`The courier, the Greek, the old man from Jerusalem, the potter and his wife, the judge, the soldier and the girl are invented, and so is what they say. The letter with shifted letters, the judge’s house and his tablet are made for the game. We do not know whether Luke ever saw Matthew’s account; most scholars think he did not. The two accounts are in Matthew 1–2 and Luke 1–2.`}}],clues:[{id:`lukas-ark`,source:{nb:`Lukas’ ark`,en:`Luke’s sheet`},text:{nb:`Engelen til Maria i Nasaret, Elisabet, folketellingen, Betlehem, krybben, gjeterne, navnet, templet, Nasaret. Josef av Davids ætt; barnet ved Ånden; under Herodes.`,en:`The angel to Mary in Nazareth, Elizabeth, the census, Bethlehem, the manger, the shepherds, the name, the temple, Nazareth. Joseph of David’s line; the child by the Spirit; under Herod.`},unlockedBy:`spor:lukas-ark`},{id:`antiokia-ark`,source:{nb:`Rullen fra Antiokia`,en:`The scroll from Antioch`},text:{nb:`Josef vil skille seg stille; engel i drømme: av Ånden, skal hete Jesus; Betlehem i Herodes’ dager; lærde menn og stjerne; guttebarna under to år drept; Egypt; Nasaret. Josef av Davids ætt.`,en:`Joseph wants to divorce quietly; angel in a dream: of the Spirit, to be called Jesus; Bethlehem in Herod’s days; learned men and a star; the boys under two killed; Egypt; Nazareth. Joseph of David’s line.`},unlockedBy:`spor:antiokia-ark`},{id:`kurer`,source:{nb:`Kureren fra Antiokia`,en:`The courier from Antioch`},text:{nb:`Matteus’ folk forteller fødselen fra Josefs side. Hyrder, krybbe, folketelling: ikke et ord. «Vi forteller det vi fikk.»`,en:`Matthew’s people tell the birth from Joseph’s side. Shepherds, manger, census: not a word. “We tell what we were given.”`},unlockedBy:`brevet-tydet`},{id:`notat`,source:{nb:`Lukas’ notat`,en:`Luke’s note`},text:{nb:`Ingen av oss har hatt den andres fortelling. Likevel samme foreldre, by, konge, navn, ætt og ord om Ånden. Det er eldre enn oss begge.`,en:`Neither of us has had the other’s story. Yet the same parents, town, king, name, line and word about the Spirit. It is older than both of us.`},unlockedBy:`spor:notat`},{id:`slektstavlene`,source:{nb:`De to slektstavlene`,en:`The two genealogies`},text:{nb:`Begge fra David til Josef. Den ene gjennom Salomo, 3 × 14 ledd, Josefs far Jakob. Den andre gjennom Natan, tilbake til Adam, Josefs far Eli. Nesten alle navn ulike fra David og ned.`,en:`Both from David to Joseph. One through Solomon, 3 × 14 generations, Joseph’s father Jacob. The other through Nathan, back to Adam, Joseph’s father Heli. Nearly all names differ from David downwards.`},unlockedBy:`spor:slektstavlene`},{id:`gammel`,source:{nb:`Den gamle fra Jerusalem`,en:`The old man from Jerusalem`},text:{nb:`Slektstavler tas alvorlig; prestenes ligger i templets arkiv. Svogerekteskap gir en gutt én far for loven og én for blodet. Om det er slik her, vet han ikke.`,en:`Genealogies are taken seriously; the priests keep theirs in the temple archive. Levirate marriage gives a boy one father for the law and one for the blood. Whether it is so here, he does not know.`},unlockedBy:`spor:gammel`},{id:`greker`,source:{nb:`Grekeren som ikke tror`,en:`The Greek who does not believe`},text:{nb:`Betlehem har begge fra profeten Mika, sier han: profetien kom først, fødestedet etterpå. Og to så ulike fortellinger kan ikke begge være sanne.`,en:`Both have Bethlehem from the prophet Micah, he says: the prophecy came first, the birthplace after. And two stories so different cannot both be true.`},unlockedBy:`spor:greker`},{id:`innvending`,source:{nb:`Grekeren som ikke tror`,en:`The Greek who does not believe`},text:{nb:`Josefs far heter Jakob hos den ene og Eli hos den andre. Forklar det.`,en:`Joseph’s father is called Jacob in the one and Heli in the other. Explain that.`},unlockedBy:`spor:innvending`},{id:`pottemaker`,source:{nb:`Pottemakeren`,en:`The potter`},text:{nb:`Kona og jeg så kjerra velte. Vi sa ulikt om det små, men likt om det store. Slik blir det når to har sett det samme.`,en:`My wife and I saw the cart tip over. We differed on the small things, but agreed on the big ones. That is how it is when two have seen the same thing.`},unlockedBy:`spor:pottemaker`},{id:`kone`,source:{nb:`Pottemakerens kone`,en:`The potter’s wife`},text:{nb:`Hun så krukkene, han så eselet; samme kjerre. Maria husket engelen og gjeterne; Josef husket drømmene sine. Hvem ellers visste om Josefs drømmer?`,en:`She saw the jars, he saw the donkey; same cart. Mary remembered the angel and the shepherds; Joseph remembered his dreams. Who else knew of Joseph’s dreams?`},unlockedBy:`spor:kone`},{id:`dommer`,source:{nb:`Dommeren`,en:`The judge`},text:{nb:`To eller tre vitner, hørt hver for seg. Ord for ord likt: øvd. Ulikt om alt: ingen. Likt om saken, ulikt om småtingene: to vitner.`,en:`Two or three witnesses, heard separately. Alike word for word: coached. Different on everything: neither. Alike on the matter, different on the small things: two witnesses.`},unlockedBy:`spor:dommer`},{id:`motsigelse`,source:{nb:`Dommeren`,en:`The judge`},text:{nb:`Den ene nevner eselet, den andre ikke: ikke motsigelse. Motsigelse er når begge ikke kan være sanne samtidig. Da velger man, eller sier at man ikke vet.`,en:`One mentions the donkey, the other does not: not contradiction. Contradiction is when they cannot both be true at once. Then you choose, or say you do not know.`},unlockedBy:`spor:motsigelse`},{id:`lovrull`,source:{nb:`Rullen med loven om vitner`,en:`The scroll with the law on witnesses`},text:{nb:`Ett vitne er ikke nok; på to eller tre vitners ord skal en sak stå.`,en:`One witness is not enough; on the word of two or three witnesses a case shall stand.`},unlockedBy:`spor:lovrull`},{id:`tavle`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`Dommerens vokstavle: to spalter, strek under hvert punkt de er enige om.`,en:`The judge’s wax tablet: two columns, a line under every point where they agree.`},unlockedBy:`spor:tavle`},{id:`mika`,source:{nb:`Rullen med Mika`,en:`The scroll of Micah`},text:{nb:`Fra Betlehem skal det komme en hersker. Antiokia-rullen siterer det; Lukas ikke. Begge har Betlehem.`,en:`From Bethlehem shall come a ruler. The Antioch scroll quotes it; Luke does not. Both have Bethlehem.`},unlockedBy:`spor:mika`},{id:`krukker`,source:{nb:`Det du selv så`,en:`What you saw yourself`},text:{nb:`To krukker fra samme leire, dreid av to hender.`,en:`Two jars from the same clay, turned by two hands.`},unlockedBy:`spor:krukker`}],deductions:[{id:`felles`,question:{nb:`Grekeren sier: begge la fødselen til Betlehem fordi Mika hadde sagt det. Stemmer det?`,en:`The Greek says both placed the birth in Bethlehem because Micah had said so. Is that right?`},clues:[`greker`,`mika`,`lukas-ark`,`antiokia-ark`],steps:[{ask:{nb:`Hva sa grekeren om Betlehem, og hva står i rullen med Mika?`,en:`What did the Greek say about Bethlehem, and what is in the scroll of Micah?`},clues:[`greker`,`mika`],yes:{nb:`Profetien først, sier han. Hvorfor var de i Betlehem, ifølge arkene?`,en:`The prophecy first, he says. Why were they in Bethlehem, according to the sheets?`},no:{nb:`Det er ikke grekeren om Betlehem, eller Mika.`,en:`That is not the Greek on Bethlehem, or Micah.`}},{ask:{nb:`Finn arket mitt og rullen fra Antiokia.`,en:`Find my sheet and the scroll from Antioch.`},clues:[`lukas-ark`,`antiokia-ark`],yes:{nb:`Hos meg: keiserens befaling. Hos dem: Mika. Stemmer det grekeren sier?`,en:`In mine: the emperor’s decree. In theirs: Micah. Is the Greek right?`},no:{nb:`Det er ikke de to fortellingene.`,en:`Those are not the two stories.`}}],options:[{text:{nb:`Nei. Jeg siterer ikke Mika; min grunn er manntallet`,en:`No. I do not quote Micah; my reason is the census`},feedback:{nb:`Riktig. Hadde Betlehem kommet fra Mika, hadde begge pekt på Mika. Profetien ble trolig funnet etterpå.`,en:`Right. Had Bethlehem come from Micah, both would have pointed to Micah. The prophecy was most likely found afterwards.`},correct:!0},{text:{nb:`Ja. Begge siterer Mika, så Betlehem er oppfylt profeti, ikke et sted noen husket`,en:`Yes. Both quote Micah, so Bethlehem is fulfilled prophecy, not a place someone remembered`},feedback:{nb:`Nei. Les arket mitt: jeg siterer ikke Mika, og jeg har en helt annen grunn til at de var der.`,en:`No. Read my sheet: I do not quote Micah, and I have quite another reason for their being there.`}},{text:{nb:`Mika sier ikke noe om Betlehem; grekeren har lest feil rull`,en:`Micah says nothing about Bethlehem; the Greek has read the wrong scroll`},feedback:{nb:`Jo, les rullen. Spørsmålet er hvem som brukte den, og når.`,en:`He does; read the scroll. The question is who used it, and when.`}}],set:[`felles-lost`]},{id:`ulikt`,question:{nb:`Hvorfor er de ulike, og er det motsigelser?`,en:`Why do they differ, and are there contradictions?`},clues:[`kurer`,`kone`,`dommer`,`motsigelse`],steps:[{ask:{nb:`Hva sa kureren om hva de har og ikke har?`,en:`What did the courier say about what they have and do not have?`},clues:[`kurer`],yes:{nb:`Josefs side: drømmer, lærde menn, Egypt, men ingen gjetere. Og kona?`,en:`Joseph’s side: dreams, learned men, Egypt, but no shepherds. And the wife?`},no:{nb:`Det er ikke kureren.`,en:`That is not the courier.`}},{ask:{nb:`Hva sa pottemakerens kone, og hva sa dommeren?`,en:`What did the potter’s wife say, and what did the judge say?`},clues:[`kone`,`dommer`,`motsigelse`],yes:{nb:`Hennes side og hans. Hva svarer vi grekeren?`,en:`Her side and his. What do we answer the Greek?`},no:{nb:`Det er ikke kona eller dommeren.`,en:`That is not the potter’s wife or the judge.`}}],options:[{text:{nb:`De forteller fra hver sin side, Josefs og Marias. Ulikt er ikke det samme som motsigelse`,en:`Each tells it from their own side, Joseph’s and Mary’s. Different is not the same as contradictory`},feedback:{nb:`Riktig. Josefs drømmer hos dem, det Maria gjemte hos meg. Ulikt er ikke motsigelse, like lite som eselet og krukkene.`,en:`Right. Joseph’s dreams are in theirs, what Mary remembered in mine. Different is not contradictory, any more than the donkey and the jars.`},correct:!0},{text:{nb:`Fordi den ene har diktet, og den andre er den ekte; grekeren har rett i at vi må velge`,en:`Because one made things up and the other is true; the Greek is right that we must choose`},feedback:{nb:`For raskt. Da hadde de ikke vært enige om alt det som bærer, uten å ha snakket sammen. Grekeren har rett i at de er ulike; han tar feil i hva det betyr.`,en:`Too hasty. Then they would not have agreed on all that bears the weight, without having compared notes. The Greek is right that they differ; he is wrong about what it means.`}},{text:{nb:`De er ikke ulike; grekeren husker feil`,en:`They are not different; the Greek remembers wrongly`},feedback:{nb:`Jo, de er ulike. Grekeren har sett begge og husker rett. Han tar feil i hva ulikheten betyr.`,en:`They are different. The Greek has seen both and remembers rightly. He is wrong about what the difference means.`}}],set:[`ulikt-lost`]},{id:`to-tavler`,question:{nb:`Hvorfor er de to slektstavlene ulike fra David og ned?`,en:`Why do the two genealogies differ from David downwards?`},clues:[`slektstavlene`,`innvending`,`gammel`],steps:[{ask:{nb:`Finn de to slektstavlene, og hør grekerens innvending.`,en:`Find the two genealogies, and hear the Greek’s objection.`},clues:[`slektstavlene`,`innvending`],yes:{nb:`Salomo mot Natan, Jakob mot Eli. Hva sa den gamle?`,en:`Solomon against Nathan, Jacob against Heli. What did the old man say?`},no:{nb:`Det handler ikke om slektstavlene.`,en:`That is not about the genealogies.`}},{ask:{nb:`Hva sa den gamle fra Jerusalem?`,en:`What did the old man from Jerusalem say?`},clues:[`gammel`],yes:{nb:`Én far for loven, én for blodet; om det er slik her, vet han ikke. Hva svarer vi?`,en:`One father by law, one by blood; whether it is so here, he does not know. What do we answer?`},no:{nb:`Det er ikke den gamle.`,en:`That is not the old man.`}}],options:[{text:{nb:`Vi vet ikke sikkert. Begge fører Josef til David, ad ulike veier`,en:`We do not know for sure. Both lead Joseph to David, by different roads`},feedback:{nb:`Riktig. Det kan være svogerekteskap, eller at den ene følger Marias slekt. Ingenting er bevist, men begge sier det som teller: Davids ætt.`,en:`Right. It may be levirate marriage, or one may follow Mary’s family. Nothing is proven, but both say what counts: David’s line.`},correct:!0},{text:{nb:`Den ene tavla er helt sikkert falsk`,en:`One of the tables is certainly false`},feedback:{nb:`Nei. «Helt sikkert» kan vi ikke si. Den gamle har sett slike tavler gå ulike veier for samme mann, lovlig. Og begge ender hos David.`,en:`No. We cannot say “certainly”. The old man has seen such tables go different ways for the same man, lawfully. And both end at David.`}},{text:{nb:`De er like fra David og ned; forskjellen er bare stavemåter og rekkefølgen på navnene`,en:`They are alike from David downwards; the difference is only spellings and the order of the names`},feedback:{nb:`Nei. Fra David og ned er nesten alle navnene ulike, og Josefs far heter Jakob hos den ene og Eli hos den andre. Det må vi innrømme.`,en:`No. From David downwards nearly all the names differ, and Joseph’s father is Jacob in the one and Heli in the other. That we must admit.`}}],set:[`to-tavler-lost`]},{id:`uavhengig`,question:{nb:`Har Lukas skrevet av Antiokia, eller de av ham?`,en:`Has Luke copied Antioch, or they him?`},clues:[`notat`,`kurer`,`pottemaker`,`krukker`],steps:[{ask:{nb:`Hva står i notatet mitt, og hva sa kureren?`,en:`What is in my note, and what did the courier say?`},clues:[`notat`,`kurer`],yes:{nb:`Ingen av oss hadde den andres fortelling. Hva sa pottemakeren?`,en:`Neither of us had the other’s story. What did the potter say?`},no:{nb:`Det er ikke notatet eller kureren.`,en:`That is not the note or the courier.`}},{ask:{nb:`Hva sa pottemakeren, og hva så du ved brønnen?`,en:`What did the potter say, and what did you see at the well?`},clues:[`pottemaker`,`krukker`],yes:{nb:`Likt om det store, ulikt om det små. To krukker, samme leire. Hva følger?`,en:`Alike in the big things, unlike in the small. Two jars, the same clay. What follows?`},no:{nb:`Det er ikke pottemakeren eller krukkene.`,en:`That is not the potter or the jars.`}}],options:[{text:{nb:`Ingen har skrevet av den andre, så det de er enige om, må være eldre enn begge`,en:`Neither copied the other; so what they agree on is older than both`},feedback:{nb:`Riktig. Hadde de skrevet av meg, hadde de hatt gjeterne; hadde jeg skrevet av dem, hadde jeg hatt de lærde mennene. Vi har begge kjernen.`,en:`Right. Had they copied me, they would have the shepherds; had I copied them, I would have the learned men. We both have the core.`},correct:!0},{text:{nb:`Lukas har skrevet av Antiokia, og tok bare bort det han ikke likte`,en:`Luke copied Antioch and left out what he did not like`},feedback:{nb:`Nei. Da hadde jeg hatt de lærde mennene og Egypt i boka mi. Jeg fikk rullen i natt.`,en:`No. Then I would have had the learned men and Egypt in my book. I got the scroll last night.`}},{text:{nb:`Begge har skrevet av en tapt bok og tatt hver sin halvdel`,en:`Both copied a lost book, and each took half`},feedback:{nb:`Nei. Hadde hver tatt sin halvdel, hadde de ikke hatt den samme kjernen. Og noen slik bok kjenner verken jeg eller kureren.`,en:`No. Had each taken half, they would not share the same core. And neither I nor the courier knows of any such book.`}}],set:[`uavhengig-lost`]},{id:`egypt`,question:{nb:`Egypt eller Nasaret: går det opp?`,en:`Egypt or Nazareth: does it add up?`},clues:[`antiokia-ark`,`lukas-ark`,`motsigelse`],steps:[{ask:{nb:`Hvor dro de etter fødselen, ifølge rullen og arket mitt?`,en:`Where did they go after the birth, according to the scroll and my sheet?`},clues:[`antiokia-ark`,`lukas-ark`],yes:{nb:`De: Egypt, og så Nasaret etter Herodes’ død. Jeg: templet etter førti dager, og så Nasaret. Og dommeren?`,en:`They: Egypt, and then Nazareth after Herod’s death. I: the temple after forty days, and then Nazareth. And the judge?`},no:{nb:`Det er ikke de to fortellingene.`,en:`Those are not the two stories.`}},{ask:{nb:`Hva sa dommeren om motsigelse?`,en:`What did the judge say about contradiction?`},clues:[`motsigelse`],yes:{nb:`Bare der begge ikke kan være sanne samtidig. Går det opp?`,en:`Only where both cannot be true at once. Does it add up?`},no:{nb:`Det er ikke dommeren om motsigelse.`,en:`That is not the judge on contradiction.`}}],options:[{text:{nb:`Det kan gå opp, men det er trangt, og det sier vi fra om`,en:`It can add up, but it is tight. A sticking point, and we say so`},feedback:{nb:`Riktig. Det kan gå opp hvis de lærde mennene kom senere og flukten fulgte etter templet. Men det kniper, og det sier jeg fra om.`,en:`Right. It can add up if the learned men came later and the flight followed the temple. But it is tight, and I say so.`},correct:!0},{text:{nb:`Nei, den ene fortellingen er umulig; de kan ikke ha vært både i Egypt og hjemme`,en:`No, one of the stories is impossible; they cannot have been both in Egypt and at home`},feedback:{nb:`For sterkt. Den ene sier Egypt, den andre sier ingenting om Egypt. Taushet er ikke motsigelse. Det er trangt i tid, men ikke umulig.`,en:`Too strong. One says Egypt, the other says nothing about Egypt. Silence is not contradiction. Time is tight, but it is not impossible.`}},{text:{nb:`Det er ingen vanskelighet her; alt går lett opp om man leser nøye`,en:`There is no difficulty here; it all adds up easily if one reads carefully`},feedback:{nb:`Jo, litt. Les arket mitt: hjem til Nasaret, som om det var straks. Vi skal ikke late som.`,en:`There is, a little. Read my sheet: home to Nazareth, as if at once. We must not pretend.`}}],set:[`egypt-lost`]},{id:`metoden`,question:{nb:`Hvordan sammenligner man to vitner, steg for steg?`,en:`How does one compare two witnesses, step by step?`},clues:[`dommer`,`motsigelse`,`lovrull`,`tavle`,`pottemaker`],steps:[{ask:{nb:`Finn dommeren, lovrullen, tavla og pottemakeren.`,en:`Find the judge, the law scroll, the tablet and the potter.`},clues:[`dommer`,`motsigelse`,`lovrull`,`tavle`,`pottemaker`],yes:{nb:`Hva gjør man først? Sett det i rekkefølge.`,en:`What does one do first? Put it in order.`},no:{nb:`Det hjelper ikke med rekkefølgen.`,en:`That does not help with the order.`}}],sequence:[{nb:`Krev minst to vitner, og hør dem hver for seg`,en:`Require at least two witnesses, and hear them separately`},{nb:`Sett strek under alt de er enige om, og sjekk at de er ulike i det små (ellers har de øvd)`,en:`Draw a line under everything they agree on, and check that they differ in the small things (otherwise they have rehearsed)`},{nb:`Spør om det ulike kan være sant samtidig, eller om det er motsigelse`,en:`Ask whether the differences can all be true at once, or whether it is contradiction`},{nb:`Der det er motsigelse: velg, eller si at du ikke vet`,en:`Where there is contradiction: choose, or say that you do not know`},{nb:`Bygg dommen på det de er enige om`,en:`Build the verdict on what they agree on`}],explained:{nb:`Slik gjør dommeren det, og slik gjør jeg det: loven om to vitner, brukt på to fortellinger om ett barn.`,en:`That is how the judge does it, and how I do it: the law of two witnesses, applied to two accounts of one child.`},set:[`metoden-lost`]}],objectives:[{text:{nb:`Snakk med Lukas`,en:`Talk to Luke`},doneBy:[`oppdrag`]},{text:{nb:`Snakk med kureren, grekeren, den gamle, pottemakeren og kona, tyd brevet fra Antiokia og se på krukkene ved brønnen`,en:`Talk to the courier, the Greek, the old man, the potter and his wife, decipher the letter from Antioch and look at the jars by the well`},doneBy:[`spor:kurer`,`spor:greker`,`spor:gammel`,`spor:pottemaker`,`spor:kone`,`brevet-tydet`,`spor:krukker`]},{text:{nb:`Les arkene i skrivestua`,en:`Read the sheets in the writing room`},doneBy:[`spor:lukas-ark`,`spor:antiokia-ark`,`spor:slektstavlene`,`spor:notat`,`spor:mika`]},{text:{nb:`Gå inn i dommerens hus`,en:`Go into the judge’s house`},doneBy:[`spor:dommer`,`spor:lovrull`,`spor:tavle`]},{text:{nb:`Løs sakene i vitneboka`,en:`Solve the cases in the notebook`},doneBy:[`felles-lost`,`ulikt-lost`,`to-tavler-lost`,`uavhengig-lost`,`egypt-lost`,`metoden-lost`]},{text:{nb:`Gå tilbake til Lukas`,en:`Go back to Luke`},doneBy:[`avsluttet`]}],rewards:[{flag:`felles-lost`,points:15,label:{nb:`Snu grekerens pil`,en:`Turn the Greek’s arrow around`}},{flag:`ulikt-lost`,points:15,label:{nb:`Skill ulikhet fra motsigelse`,en:`Tell difference from contradiction`}},{flag:`to-tavler-lost`,points:15,label:{nb:`La spørsmålet stå åpent`,en:`Leave the question open`}},{flag:`uavhengig-lost`,points:20,label:{nb:`Finn kjernen som er eldre enn begge`,en:`Find the core older than both`}},{flag:`egypt-lost`,points:10,label:{nb:`Si fra der det kniper`,en:`Speak up where it gets tight`}},{flag:`metoden-lost`,points:10,label:{nb:`Lær dommerens metode`,en:`Learn the judge’s method`}},{flag:`avsluttet`,points:10,label:{nb:`Fullfør dagen med Lukas`,en:`Finish the day with Luke`}},{flag:`spor:soldat`,points:5,label:{nb:`Hør om Herodes`,en:`Hear about Herod`},side:!0},{flag:`spor:krukker`,points:5,label:{nb:`Se de to krukkene`,en:`See the two jars`},side:!1},{flag:`bit:1`,points:2,label:{nb:`Finn en rullbit`,en:`Find a scroll piece`},side:!0},{flag:`bit:2`,points:2,label:{nb:`Finn en rullbit`,en:`Find a scroll piece`},side:!0},{flag:`bit:3`,points:2,label:{nb:`Finn en rullbit`,en:`Find a scroll piece`},side:!0},{flag:`bit:4`,points:2,label:{nb:`Finn en rullbit`,en:`Find a scroll piece`},side:!0},{flag:`rull-helet`,points:12,label:{nb:`Finn de fire bitene av Antiokia-rullen`,en:`Find the four pieces of the Antioch scroll`},side:!0},{flag:`to-vitner-hort`,points:12,label:{nb:`Hent pottemakerens og konas vitnemål til dommeren`,en:`Fetch the potter’s and his wife’s statements for the judge`},side:!0},{flag:`krukkene-truffet`,points:10,label:{nb:`Treff krukkene`,en:`Hit the jars`},side:!0},{flag:`brevet-tydet`,points:10,label:{nb:`Tyd brevet`,en:`Decode the letter`},side:!0}],inventory:[{icon:`📜`,label:{nb:`Rullbiter`,en:`Scroll pieces`},flags:[`bit:1`,`bit:2`,`bit:3`,`bit:4`],goneWhen:`rull-helet`},{icon:`📝`,label:{nb:`Vitnetavler`,en:`Witness tablets`},flags:[`tavle-hans`,`tavle-hennes`],goneWhen:`to-vitner-hort`}],ambience:[{sound:`sea`,x:8,y:16,radius:8},{sound:`sea`,x:16,y:16,radius:8},{sound:`sea`,x:23,y:16,radius:8},{sound:`market`,x:12,y:4,radius:5},{sound:`market`,x:21,y:6,radius:5},{sound:`market`,x:15,y:8,radius:4}],goal:[`avsluttet`],solution:`lukas.kurer.kurer.greker.gammel.pottemaker.pottemaker.kone.jente.soldat.to-krukker.rullbit-1.rullbit-2.rullbit-3.rullbit-4.kurer.dor-skrivestue.lukas-ark.antiokia-ark.slektstavlene.notat.mika.dor-ut-skrivestue.dor-dommerhus.dommer.lovrull.tavle.dor-ut-dommerhus.pottemaker.kone.dor-dommerhus.dommer.dor-ut-dommerhus.felles.ulikt.to-tavler.uavhengig.egypt.metoden.lukas`.split(`.`)};export{e as default};